import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.DTwTvi8b.js";const q=JSON.parse('{"title":"req-kit 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1791966569000}'),o={name:"guide/index.md"};function i(l,t,n,s,h,u){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="req-kit-是什么" tabindex="-1">req-kit 是什么 <a class="header-anchor" href="#req-kit-是什么" aria-label="Permalink to &quot;req-kit 是什么&quot;">​</a></h1><p>req-kit 是运行在 <a href="https://paseo.sh" target="_blank" rel="noreferrer">Paseo</a> 上的一套<strong>需求开发体系</strong>。它帮助非专职开发、但有一定技术背景的同事——测试、产品经理、项目经理——把一个需求从&quot;我想要……&quot;推进到&quot;可以验收&quot;：</p><ul><li>你在 Paseo 的对话里输入 <code>/req</code> 和一句话，AI 用访谈的方式和你把需求谈清楚，写成一份需求说明（<code>spec.md</code>）请你确认。</li><li>确认后，一组 AI agent 在后台依次完成方案设计、方案审核、代码实现、代码评审、服务启动、功能验证、缺陷修复和完成报告。</li><li>进展、需要你决定的问题和最终结论都发回同一个对话；你再按验收标准逐条验收。</li></ul><p>整个过程只在本地提交代码，合并和上线仍然由人决定。</p><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p>直接让一个编码 agent &quot;把这个需求做了&quot;，常见的问题是：</p><table tabindex="0"><thead><tr><th>问题</th><th>req-kit 的做法</th></tr></thead><tbody><tr><td>需求没谈清楚就开工，做出来不是想要的</td><td>先访谈，一次一个问题，给选项和推荐；确认前另一个模型独立审阅需求说明</td></tr><tr><td>自己写、自己检查，问题被忽略</td><td>做事的和检查的是不同的 agent，可以配置不同的模型；评审小组可以并行审核</td></tr><tr><td>说&quot;做完了&quot;，其实没验证</td><td>验证由独立的 agent 按验收标准逐条进行，结论必须有证据；报告从严判定</td></tr><tr><td>过程不可见，出了问题无从查起</td><td>每一步是一个挂在你对话下的子 agent，产物都是功能目录里的文件</td></tr><tr><td>一跑几个小时，中途断了要重来</td><td>中断后从断点继续；需求变了只处理变化的部分；临时错误自动重试、自动继续</td></tr></tbody></table><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><ul><li><strong>测试同事</strong>：把测试中发现的小需求、改进自己推进；也可以作为&quot;测试阶段&quot;的接手人，按提测说明在测试环境中验证。</li><li><strong>产品经理</strong>：把需求讲清楚，拿到可以试用的结果和一份讲人话的报告。</li><li><strong>项目经理</strong>：用需求总览（<code>req digest</code>）看所有需求的状态，接入企业 IM 收通知。</li><li><strong>开发同事</strong>：负责安装、项目接入（<code>/req-setup</code>）和代码合并；也可以直接用它推进小需求。</li></ul><h2 id="它不做什么" tabindex="-1">它不做什么 <a class="header-anchor" href="#它不做什么" aria-label="Permalink to &quot;它不做什么&quot;">​</a></h2><ul><li>不合并、不推送、不上线，不连接生产环境，不使用生产凭据。</li><li>不替代代码审查：报告的附录写明了分支、提交和改动，由开发同事审阅后合并。</li><li>不追求通用的编码提效，见 <a href="/paseo-req-kit/reference/scope">范围与取舍</a>。</li></ul><h2 id="支持的环境" tabindex="-1">支持的环境 <a class="header-anchor" href="#支持的环境" aria-label="Permalink to &quot;支持的环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Paseo</td><td>0.11（daemon 在运行；网页版或桌面版都可以）</td></tr><tr><td>Node.js</td><td>22 或更新</td></tr><tr><td>系统</td><td>macOS、Linux、Windows</td></tr><tr><td>agent</td><td>Claude Code、Codex、OpenCode、Pi 中至少一种，已在 Paseo 中登录</td></tr></tbody></table><p>下一步：<a href="./getting-started">快速开始</a>。</p>',14)])])}const p=e(o,[["render",i]]);export{q as __pageData,p as default};
